-- SQLite: NULL은 미채점, 0은 채점된 실제 점수입니다.
PRAGMA foreign_keys=ON;
CREATE TABLE student(id TEXT PRIMARY KEY NOT NULL);
CREATE TABLE course(id TEXT PRIMARY KEY NOT NULL);
CREATE TABLE term(id TEXT PRIMARY KEY NOT NULL);
CREATE TABLE enrollment(student TEXT NOT NULL REFERENCES student(id),
 course TEXT NOT NULL REFERENCES course(id), term TEXT NOT NULL REFERENCES term(id),
 score INTEGER CHECK(score IS NULL OR (typeof(score)='integer' AND score BETWEEN 0 AND 100)),
 PRIMARY KEY(student,course,term));
INSERT INTO student VALUES ('S1'),('S2');
INSERT INTO course VALUES ('C1');
INSERT INTO term VALUES ('spring'),('fall');
INSERT INTO enrollment VALUES ('S1','C1','spring',70),('S1','C1','fall',90),('S2','C1','fall',NULL);
SELECT AVG(score) FROM enrollment WHERE course='C1' AND term='fall';
